void vCheckWindowBounds(HWND hWnd)

{
  bool b_out_of_bounds;
  RECT r_window_rect;
  RECT r_work_area;
  
  if (giGameScreenMode_2 == 0) {
    SystemParametersInfoA(0x30,0,&r_work_area,0);
    GetWindowRect(hWnd,&r_window_rect);
    if (r_work_area.right < r_window_rect.right) {
      r_window_rect.left = r_window_rect.left + (r_work_area.right - r_window_rect.right);
    }
    if (r_work_area.bottom < r_window_rect.bottom) {
      r_window_rect.top = r_window_rect.top + (r_work_area.bottom - r_window_rect.bottom);
    }
    b_out_of_bounds = r_window_rect.left < 0;
    if (b_out_of_bounds) {
      r_window_rect.left = 0;
    }
    if (r_window_rect.top < 0) {
      r_window_rect.top = 0;
    }
    else if (!b_out_of_bounds &&
             (r_work_area.bottom >= r_window_rect.bottom && r_work_area.right >= r_window_rect.right
             )) {
      return;
    }
    SetWindowPos(hWnd,(HWND)0x0,r_window_rect.left,r_window_rect.top,0,0,5);
  }
  return;
}



